CREATE OR REPLACE FUNCTION public.phase6_can_finance(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$ SELECT public.has_role(_uid, 'admin') OR public.has_permission(_uid, 'finance.view') OR public.has_permission(_uid, 'finance.edit'); $$; CREATE OR REPLACE FUNCTION public.phase6_can_quality(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path = public AS $$ SELECT public.has_role(_uid, 'admin') OR public.has_permission(_uid, 'quality.view') OR public.has_permission(_uid, 'quality.edit'); $$;